const first = $input.first() && $input.first().json;
if (first && first.error) throw new Error(`Couldn't read your Shopify products: ${errText(first.error)}. Check the Shopify Access Token credential (read_products scope).`);
let base = String(s.shopify_store_url || '').trim().replace(/\/+$/, '');
