const input = $input.all();
const fromAi = input.length > 0 && !('product_key' in input[0].json);
const tags = String(s.extra_hashtags || '').split(/[\s,]+/).filter(Boolean).map(t => '#' + t.replace(/^#+/, '')).join(' ');
const footer = String(s.business_footer || '').trim();
const one = t => String(t || '').replace(/\s+/g, ' ').trim();
const keepLines = (t, n) => { t = String(t || '').replace(/[ \t]+/g, ' ').replace(/\n{3,}/g, '\n\n').trim(); return t.length <= n ? t : cut(t, n); };
const GUARD = [['discount', /\bdiscount/i], ['sale', /\bsale\b/i], ['% off', /\d+\s?%\s?off/i], ['coupon', /coupon|promo code/i],
  ['review', /\breview/i], ['rating', /\brating|\brated\b/i], ['stars', /\b\d(\.\d)?\s?stars?\b|\u2605/i], ['bestseller', /best[\s-]?sell/i],
  ['stock', /only \d+ left|limited stock|low stock|almost gone|selling fast|last (one|few)/i], ['free shipping', /free (shipping|delivery)/i],
  ['testimonial', /testimonial|customers (love|say)|our customers/i], ['price', /[$\u20ac\u00a3\u00a5]\s?\d|\d+([.,]\d+)?\s?(usd|eur|gbp|cad|aud)\b/i]];
const out = products.map((item, i) => {
  const p = item.json;
  const src = [p.title, p.description_text, (p.tags || []).join(' '), (p.materials || []).join(' ')].join(' ').toLowerCase();
  const shortTitle = cut(one(String(p.title).split(/\s[\u2022|\u00b7]\s|\s[-\u2013]\s|,\s/)[0]), 60) || cut(one(p.title), 60);
  // Template copy uses the first real sentences of the listing (skips spaced-out headings like "D I A M O N D" and short bullet lines).
  const prose = String(p.description_text || '').split(/\n+/).map(l => l.replace(/^[\s\u2022*\-\u2013\u00b7\u2219]+/, '').trim())
    .filter(l => l.length >= 25 && !/^(\S[ \u2219]+){4,}/.test(l)).join(' ');
  const firstText = n => cut(one(prose || p.description_text), n);
  const template = {
    short_name: shortTitle,
    pinterest_title: (() => { const parts = one(p.title).split(/\s*[\u2022|\u00b7]\s*/).filter(Boolean); let t = '';
      for (const part of parts) { const next = t ? `${t}, ${part}` : part; if (next.length > 100) break; t = next; }
      return t || cut(one(p.title), 100); })(),
    pinterest_description: cut(`${shortTitle} from ${p.shop_name}. ${firstText(380)}`, 450),
    instagram_caption: `${shortTitle} from ${p.shop_name}.\n\n${firstText(400)}`,
    facebook_caption: `${shortTitle} from ${p.shop_name}.`, threads_caption: `${shortTitle} from ${p.shop_name}.`,
  };
  let copy = template, copySource = fromAi ? 'template (OpenAI failed)' : 'template (use_openai is off)';
  if (fromAi) {
    const r = input[i] && input[i].json;
    const o = r && (r.output || r);
    if (o && o.pinterest_title && o.instagram_caption && !r.error) {
      const ai = { ...template, ...Object.fromEntries(Object.entries(o).filter(([, v]) => typeof v === 'string' && v.trim())) };
      const text = Object.values(ai).join(' ');
      const hits = GUARD.filter(([, re]) => re.test(text) && !re.test(src)).map(([k]) => k);
      if (hits.length) copySource = `template (AI copy mentioned ${hits.join(', ')}, which is not in the listing)`;
      else { copy = ai; copySource = 'openai'; }
    } else if (r && r.error) copySource = `template (OpenAI error: ${errText(r.error)})`;
  }
  const priceLine = s.include_price && p.price_text ? `${s.price_label || 'Price when posted:'} ${p.price_text}` : '';
  const link = (() => { const extra = String(s.link_tracking_params || '').replace(/^[?&]/, '').trim(); return extra ? p.url + (p.url.includes('?') ? '&' : '?') + extra : p.url; })();
  const cta = String(s.instagram_call_to_action || '').replace(/\{shop\}/g, p.shop_name).trim();
  const pinCount = Math.min(5, Math.max(1, Math.round(Number(s.pin_image_count) || 1)));
  const carCount = Math.min(10, Math.max(2, Math.round(Number(s.instagram_carousel_images) || 5)));
  const igImages = (p.ig_images || []).map(img => img.url);
  return { json: {
    product_key: p.product_key, source: p.source, title: p.title, product_url: p.url, price_text: p.price_text, copy_source: copySource,
    pinterest_account_id: board.pinterest_account_id, pinterest_board_id: board.pinterest_board_id, pinterest_board_name: board.pinterest_board_name,
    pinterest_ready: board.pinterest_ready, pinterest_note: board.pinterest_note,
    pin_title: cut(one(copy.pinterest_title), 100),
    pin_description: cut([one(copy.pinterest_description), priceLine, footer].filter(Boolean).join(' '), 500),
    alt_text: cut(`Product photo: ${one(copy.short_name) || shortTitle}`, 500),
    pin_link: link.length <= 2048 ? link : p.url,
    pin_image_urls: p.images.slice(0, pinCount).map(img => img.url),
    instagram_caption: keepLines([String(copy.instagram_caption || '').trim(), priceLine, cta, tags, footer].filter(Boolean).join('\n\n'), 2200),
    instagram_image_url: igImages[0] || '',
    instagram_carousel_urls: igImages.slice(0, carCount),
    instagram_note: igImages.length ? '' : 'No product photo fits Instagram (4:5 to 1.91:1), so Instagram was skipped for this product.',
    facebook_caption: keepLines([one(copy.facebook_caption), priceLine, link, footer].filter(Boolean).join('\n\n'), 5000),
    threads_caption: cut([one(copy.threads_caption), link].filter(Boolean).join(' '), 500),
  }, pairedItem: { item: i } };
});
return out;

const errText = e => !e ? '' : (typeof e === 'string' ? e : (e.message || e.description || e.detail || JSON.stringify(e))).toString().slice(0, 300);
const decode = t => String(t || '')
  .replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&#0?39;|&apos;/g, "'")
  .replace(/&#(\d+);/g, (m, n) => String.fromCodePoint(Number(n))).replace(/&#x([0-9a-f]+);/gi, (m, n) => String.fromCodePoint(parseInt(n, 16)))
  .replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&');
const htmlToText = h => decode(String(h || '').replace(/<br\s*\/?>/gi, '\n').replace(/<\/(p|div|li|h\d)>/gi, '\n').replace(/<[^>]+>/g, ' '))
  .replace(/[ \t]+/g, ' ').replace(/ *\n */g, '\n').replace(/\n{3,}/g, '\n\n').trim();
const cut = (t, n) => { t = String(t || '').trim(); if (t.length <= n) return t; const c = t.slice(0, n - 1); const sp = c.lastIndexOf(' '); return (sp > n * 0.6 ? c.slice(0, sp) : c).replace(/[\s,.;:\u2013-]+$/, '') + '\u2026'; };
const cleanUrl = u => { try { const x = new URL(String(u || '').trim()); if (!/^https?:$/.test(x.protocol)) return ''; x.search = ''; x.hash = ''; return x.toString(); } catch (e) { return ''; } };
const igFit = img => !(img.width > 0 && img.height > 0) || (img.width / img.height >= 0.8 && img.width / img.height <= 1.91);
const finish = (list, s, label) => {
  const products = list.filter(p => p.url && p.images.length)
    .map(p => ({ ...p, ig_images: p.images.filter(igFit) }))
    .sort((x, y) => s.post_order === 'oldest_first' ? x.created_ms - y.created_ms : y.created_ms - x.created_ms);
  if (!products.length) throw new Error(`${label}: no products with a photo and a link were found. Check your shop settings in ${'Configure Catalog Settings'}.`);
  return products.map(p => ({ json: p }));
};
// One summary per product. Disabled nodes are skipped. Pinterest and Instagram errors are shown in plain words.
const built = $('Assemble Social Media Post').all();
const runOf = name => { try { return $(name).all(); } catch (e) { return null; } };
const nets = [['pinterest', 'Post Pinterest Pin via SocialRobot API'], ['instagram', 'Post Instagram Photo'], ['instagram_carousel', 'Post Instagram Carousel via SocialRobot API'], ['facebook', 'Post Facebook Photo'], ['threads', 'Post Threads Photo']];
// A disabled node passes its input through unchanged, so an item equal to the previous node's item means "did not run".
const chain = ['Assemble Social Media Post', ...nets.map(([, name]) => name)];
const results = nets.map(([key, name], k) => [key, name, runOf(name), runOf(chain[k])]);
return built.map((b, i) => {
  const p = b.json;
  const posted = {}, errors = {};
  for (const [key, name, items, prev] of results) {
    if (!items) continue;
    const r = items[i] && items[i].json;
    const before = prev && prev[i] && prev[i].json;
    if (!r || (before && JSON.stringify(r) === JSON.stringify(before))) continue;
    if (r.id && !r.error) posted[key] = String(r.id);
    else if (r.error || r.message) {
      let msg = errText(r.error || r.message);
      if (key.startsWith('instagram') && p.instagram_note) msg = p.instagram_note;
      errors[key] = msg;
    }
  }
  return { json: {
    product_key: p.product_key, source: p.source, title: p.title, product_url: p.product_url,
    pinterest_post_id: posted.pinterest || '', instagram_post_id: posted.instagram || posted.instagram_carousel || '',
    facebook_post_id: posted.facebook || '', threads_post_id: posted.threads || '',
    posted_networks: Object.keys(posted).join(', '), errors, copy_source: p.copy_source,
    pinterest_board: p.pinterest_board_name, posted_at: new Date().toISOString(), any_posted: Object.keys(posted).length > 0,
    error_message: Object.keys(posted).length ? '' : `Nothing was posted for "${p.title}". ` + (Object.entries(errors).map(([k, v]) => `${k}: ${v}`).join(' | ') || 'Every posting node is disabled.'),
  }, pairedItem: { item: i } };
});
